const sql={retail:`SELECT customer_id, count(*) AS orders, sum(net_amount) AS revenue\nFROM silver.orders\nGROUP BY customer_id\nORDER BY orders DESC\nLIMIT 20;`,mobility:`WITH ranked AS (\n  SELECT *, row_number() OVER (PARTITION BY trip_id ORDER BY loaded_at DESC) rn\n  FROM bronze.trips\n  WHERE trip_date = DATE '2026-09-17'\n)\nSELECT * EXCLUDE (rn) FROM ranked WHERE rn = 1;`,energy:`SELECT turbine_id, date_trunc('hour', event_ts) hour, avg(power_mw) avg_power\nFROM silver.telemetry\nWHERE event_date = DATE '2026-09-17'\nGROUP BY ALL;`,finance:`SELECT account_id, transaction_ts, amount,\n lag(amount) OVER (PARTITION BY account_id ORDER BY transaction_ts) previous_amount\nFROM silver.transactions;`};
const py={retail:`from pyspark.sql import functions as F\n\norders = spark.table("silver.orders")\nsegments = spark.table("silver.dim_customer_segment")\n\nresult = (orders\n    .filter(F.col("net_amount") > 0)\n    .join(F.broadcast(segments), "segment_id")\n    .groupBy("customer_id")\n    .agg(F.sum("net_amount").alias("revenue"),\n         F.count("*").alias("orders")))`,mobility:`from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\n\nw = Window.partitionBy("trip_id").orderBy(F.col("loaded_at").desc())\nclean = (spark.table("bronze.trips")\n    .withColumn("rn", F.row_number().over(w))\n    .filter(F.col("rn") == 1).drop("rn"))`,energy:`from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\n\nsensors = spark.table("silver.dim_sensor")\ntelemetry = spark.table("silver.telemetry")\nresult = telemetry.join(F.broadcast(sensors), "sensor_id")`,finance:`from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\n\nw = Window.partitionBy("account_id").orderBy("transaction_ts")\nresult = spark.table("silver.transactions").withColumn("previous_amount", F.lag("amount").over(w))`};
