const tabs=['Overview','Notebook','Spark Lab','Pipeline','dbt','Lakehouse','Quality','Consumer','Advanced'];
let caseId='retail',mission=2,tab='Overview',mode='PySpark',ran=false,env='MotherDuck',cluster='fabric_f64_like',planMode='optimized',sparkUi='Stages';
const root=document.querySelector('#root');
function c(){return cases[caseId]}
function render(){root.innerHTML=`<div class="lab-shell"><header class="lab-topbar"><div class="brand"><div class="brand-mark">D</div><div><strong>DuckLake Data Engineering Lab</strong><span>Real lakehouse · Spark notebook training</span></div></div><label class="case-picker"><span>CASE STUDY</span><select id="caseSel">${Object.entries(cases).map(([k,v])=>`<option value="${k}" ${k===caseId?'selected':''}>${v.name}</option>`).join('')}</select></label><div class="env-toggle"><button data-env="Local DuckDB" class="${env==='Local DuckDB'?'active':''}">Local</button><button data-env="MotherDuck" class="${env==='MotherDuck'?'active':''}">MotherDuck</button></div><span class="release">V0.5 · Virtual Runtime</span></header><div class="lab-grid"><aside class="left-rail">${left()}</aside><main class="center-panel">${head()}<nav class="tabs">${tabs.map(x=>`<button data-tab="${x}" class="${tab===x?'active':''}">${x}</button>`).join('')}</nav><div class="main-scroll">${page()}</div></main><aside class="right-rail">${inspector()}</aside></div></div>`;bind()}
function left(){return `<div class="case-summary"><span>LEARNING PATH</span><strong>${c().short}</strong><p>${c().desc}</p><div class="focus-tags">${c().focus.map(x=>`<em>${x}</em>`).join('')}</div></div><div class="missions">${c().missions.map((m,i)=>`<button data-mission="${i}" class="${i===mission?'selected':''}"><b>${m[0]}</b><div><span>${m[1]}</span><strong>${m[2]}</strong><small>${m[1]==='Spark'?'distributed reasoning':'data engineering'}</small></div></button>`).join('')}</div>`}
function head(){let m=c().missions[mission];return `<section class="mission-head"><div><span>${c().name} / ${m[1]}</span><h1>${m[2]}</h1><p>Practice the real data operation and inspect the lake/runtime evidence.</p></div><div class="truth-badge"><span>CORE FORMAT</span><strong>Parquet → DuckLake</strong></div></section>`}
const intro=(e,t,p)=>`<div class="intro"><span>${e}</span><h2>${t}</h2><p>${p}</p></div>`;
const metric=(l,v)=>`<div class="metric"><span>${l}</span><strong>${v}</strong></div>`;
function overview(){return `<div class="page">${intro('PRODUCT MODEL','Real lakehouse + deterministic virtual Spark cluster','The result path stays real through DuckDB/MotherDuck/Polars while SparkLab models executors, task waves, AQE, capacity and cost from pre-engineered truth packs.')}<div class="architecture-flow"><div class="arch"><strong>Case Parquet</strong><span>known rows · files · keys</span></div><i class="arrow">→</i><div class="arch"><strong>DuckDB / MotherDuck</strong><span>real SQL + statistics</span></div><i class="arrow">→</i><div class="arch strong"><strong>DuckLake</strong><span>Bronze · Silver · Gold</span></div><i class="arrow">→</i><div class="arch-split"><div class="arch"><strong>SQL Notebook</strong><span>real execution</span></div><div class="arch"><strong>PySpark Notebook</strong><span>training syntax</span></div></div><i class="arrow">→</i><div class="arch-split"><div class="arch"><strong>DuckDB / Polars</strong><span>real result engine</span></div><div class="arch warn"><strong>SparkLab</strong><span>stages · shuffle · skew</span></div></div></div><div class="truth-grid"><div class="truth real"><strong>REAL</strong><span>• Parquet values + schemas</span><span>• DuckDB/MotherDuck queries</span><span>• DuckLake snapshots</span><span>• Polars outputs</span></div><div class="truth sim"><strong>DATASET-GROUNDED SIMULATION</strong><span>• Spark stages</span><span>• partitions + shuffle</span><span>• skew + broadcast</span><span>• spill/AQE coaching</span></div><div class="truth no"><strong>NOT CLAIMED</strong><span>• real network shuffle</span><span>• JVM GC</span><span>• executor loss</span><span>• cluster wall clock</span></div></div><div class="section-title"><span>Case studies designed around real Spark problems</span></div><div class="case-cards">${Object.entries(cases).map(([k,v])=>`<button data-case="${k}" class="${k===caseId?'active':''}"><span>${v.short}</span><strong>${v.name}</strong><p>${v.desc}</p><div>${v.focus.map(x=>`<em>${x}</em>`).join('')}</div></button>`).join('')}</div></div>`}
function notebook(){let code=mode==='SQL'?sql[caseId]:py[caseId],m=c().missions[mission];return `<div class="page">${intro('NOTEBOOK',`${mode} · ${c().short}`,mode==='SQL'?`Real query path: ${env} executes against DuckLake/Parquet.`:'Write transferable PySpark syntax. Supported operators map to the real result path while Spark distributed behavior is modeled separately.')}<div class="mission-brief"><div><span>CURRENT MISSION</span><strong>${m[0]} · ${m[2]}</strong></div><p>${m[1]} · practice the operation with real case data.</p><div><b>Evidence:</b> real rows + lakehouse state</div></div><div class="engine-tabs"><button data-mode="SQL" class="${mode==='SQL'?'active':''}">SQL · real</button><button data-mode="PySpark" class="${mode==='PySpark'?'active':''}">PySpark · training</button></div><div class="notebook-cell"><div class="gutter">[1]</div><div><div class="cell-toolbar"><span>${mode==='SQL'?'DuckDB SQL':'PySpark-compatible training API'}</span><button id="run">▶ Run cell</button></div><pre class="prototype-code">${esc(code)}</pre></div></div><div class="result-card ${ran?'done':''}"><div><span>${ran?'EXECUTION RESULT':'RESULT PATH'}</span><strong>${ran?'Real values returned; Spark model updated':'Run against known case-study data'}</strong></div><div class="result-metrics">${metric('Rows scanned',c().metrics.input)}${metric('Input',c().metrics.bytes)}${metric('Output',c().metrics.output)}${metric('Snapshot','#'+(c().snapshot+(ran?1:0)))}</div></div>${mode==='PySpark'?`<div class="boundary-note"><strong>Truth boundary</strong><span>The transformation result is real through DuckDB/MotherDuck or Polars. Spark JVM, executor network and scheduler are not running.</span></div>`:''}</div>`}
function sparklab(){let m=c().metrics,missionRow=c().missions[mission],bars=Array.from({length:24},(_,i)=>caseId==='retail'&&i===16?m.largest:Math.round(m.median*(.58+((i*37)%71)/100))),max=Math.max(...bars);let labels={generic_8x8:'SparkLab Generic · 64 cores',fabric_f64_like:'Fabric-like F64 · up to 128 Spark vCores',databricks_jobs_like:'Databricks-like Jobs · up to 96 cores'};let run=runtimePreview.profiles[cluster][planMode],other=runtimePreview.profiles[cluster][planMode==='optimized'?'baseline':'optimized'],improvement=Math.round((1-run.duration_s/other.duration_s)*100);let runtime=caseId==='retail'?`<div class="section-title"><span>Virtual cluster runtime</span></div><div class="runtime-controls"><label><span>CLUSTER PROFILE</span><select id="clusterSel"><option value="generic_8x8" ${cluster==='generic_8x8'?'selected':''}>SparkLab Generic</option><option value="fabric_f64_like" ${cluster==='fabric_f64_like'?'selected':''}>Fabric-like F64</option><option value="databricks_jobs_like" ${cluster==='databricks_jobs_like'?'selected':''}>Databricks-like Jobs</option></select></label><div class="runtime-segment"><button data-plan="baseline" class="${planMode==='baseline'?'active':''}">Baseline · SortMerge</button><button data-plan="optimized" class="${planMode==='optimized'?'active':''}">Optimized · Broadcast + AQE</button></div><span class="aqe-chip">AQE ON · 10 MB broadcast · 64 MB advisory · skew 5× & 256 MB</span></div><div class="runtime-hero"><div><span>VIRTUAL CLUSTER</span><strong>${labels[cluster]}</strong><small>Mathematical scheduler; no executor containers.</small></div><div><span>SIMULATED WALL CLOCK</span><strong>${run.duration_s.toFixed(1)} s</strong><small>${planMode==='optimized'&&improvement>0?improvement+'% faster than baseline':'reference plan'}</small></div><div><span>SHUFFLE WRITE</span><strong>${run.shuffle_gb.toFixed(1)} GB</strong><small>${planMode==='optimized'?'Join shuffle avoided; groupBy remains':'Join + groupBy exchanges'}</small></div><div><span>SPARKLAB COST</span><strong>€${run.cost.sparklab.estimated_eur.toFixed(3)}</strong><small>${run.cost.sparklab.scc.toFixed(3)} SCC · training price</small></div></div><div class="spark-ui-shell"><div class="spark-ui-title"><div><span>SPARK UI · SIMULATED</span><strong>Job 7 · Retail customer revenue</strong></div><div class="spark-ui-tabs">${['Stages','Plan','Executors','Cost','Workspace'].map(x=>`<button data-sparkui="${x}" class="${sparkUi===x?'active':''}">${x}</button>`).join('')}</div></div>${sparkUi==='Stages'?`<div class="runtime-stage-list">${run.stages.map(s=>`<div><div class="runtime-stage-main"><b>Stage ${s.id}</b><strong>${s.name}</strong><span>${s.tasks} tasks · ${s.workers} workers · ${s.slots} slots</span></div><div class="runtime-stage-metrics"><span>duration <b>${s.duration_s.toFixed(2)}s</b></span><span>P50 task <b>${s.p50_task_s.toFixed(2)}s</b></span><span>max task <b>${s.max_task_s.toFixed(2)}s</b></span><span>max partition <b>${s.max_partition_mb.toFixed(0)} MB</b></span></div>${s.notes.map(n=>`<small>${n}</small>`).join('')}</div>`).join('')}</div>`:sparkUi==='Plan'?`<div class="aqe-plan-grid"><div><span>INITIAL PLAN</span><strong>SortMergeJoin</strong><pre>Exchange hash(segment_id)\nSortMergeJoin\nExchange hash(customer_id)\nHashAggregate</pre></div><div class="plan-arrow">→</div><div class="final"><span>AQE / OPTIMIZED PLAN</span><strong>${planMode==='optimized'?'BroadcastHashJoin':'SortMergeJoin'}</strong><pre>${planMode==='optimized'?'BroadcastExchange 6.4 MB\nBroadcastHashJoin\nExchange hash(customer_id)\nAQE split skewed partition\nHashAggregate':'Exchange hash(segment_id)\nSortMergeJoin\nExchange hash(customer_id)\nAQE split skewed partition\nHashAggregate'}</pre></div></div>`:sparkUi==='Executors'?`<div class="executor-grid">${Array.from({length:Math.min(8,Math.max(...run.stages.map(s=>s.workers)))},(_,i)=>`<div><span>executor-${i+1}</span><strong>8 cores · 64 GB</strong><small>${i===3&&planMode==='baseline'?'hot task pressure':'healthy · dynamic allocation'}</small><div class="executor-load ${i===3&&planMode==='baseline'?'hot':''}"><i style="width:${52+((i*17)%39)}%"></i></div></div>`).join('')}</div>`:sparkUi==='Cost'?`<div class="cost-grid"><div><span>SPARKLAB</span><strong>${run.cost.sparklab.scc.toFixed(3)} SCC</strong><b>€${run.cost.sparklab.estimated_eur.toFixed(3)}</b><small>Our transparent training price.</small></div><div><span>FABRIC-LIKE</span><strong>${run.cost.fabric_like.cu_hours==null?'—':run.cost.fabric_like.cu_hours.toFixed(4)+' CUh'}</strong><b>price input required</b><small>Usage equivalent only; not an Azure invoice.</small></div><div><span>DATABRICKS-LIKE</span><strong>${run.cost.databricks_like.dbu_equivalent==null?'—':run.cost.databricks_like.dbu_equivalent.toFixed(4)+' DBU-eq'}</strong><b>dated list price required</b><small>V0.5 does not invent vendor prices.</small></div></div>`:`<div class="capacity-view"><div class="capacity-meter"><span>Fabric-like shared capacity</span><strong>${runtimePreview.workspace.used_cores} / ${runtimePreview.workspace.capacity_cores} cores allocated</strong><div><i style="width:${runtimePreview.workspace.used_cores/runtimePreview.workspace.capacity_cores*100}%"></i></div><small>${runtimePreview.workspace.available_cores} cores free</small></div><div class="workload-list">${runtimePreview.workspace.running.map(w=>`<div class="running"><span>RUNNING</span><strong>${w.name}</strong><small>${w.requested_cores} cores · ${w.duration_min} min</small></div>`).join('')}${runtimePreview.workspace.queued.map(w=>`<div class="queued"><span>QUEUED</span><strong>${w.name}</strong><small>requests ${w.requested_cores} cores · waits for capacity</small></div>`).join('')}</div></div>`}</div><div class="truth-confidence"><div><span>SEMANTIC RESULT</span><strong>100%</strong><small>verified path</small></div><div><span>PARTITION DISTRIBUTION</span><strong>96%</strong><small>truth pack</small></div><div><span>JOIN STRATEGY</span><strong>97%</strong><small>rule driven</small></div><div><span>SHUFFLE BYTES</span><strong>92%</strong><small>modeled</small></div><div><span>WALL CLOCK</span><strong>78%</strong><small>estimate</small></div><div><span>CLOUD COST</span><strong>74%</strong><small>usage adapter</small></div></div><div class="grading-contract"><div><span>EXERCISE TRUTH PACK</span><strong>Grade outcomes, not source-string equality</strong><small>Semantic 45% · engineering 25% · performance 20% · cost 10%</small></div><div><b>PASS INTENT</b><span>customer grain · revenue metric · valid join · broadcast opportunity · downstream shuffle understood</span></div><div><b>ANTI-PATTERNS</b><span>repartition(1) · collect/toPandas on fact · unjustified repartition</span></div></div>`:`<div class="runtime-foundation-note"><strong>V0.5 scheduler calibration starts with Retail</strong><span>Other cases keep the existing stage model until their truth packs are pre-engineered and validated.</span></div>`;return `<div class="page"><div class="mission-brief compact"><div><span>CURRENT MISSION</span><strong>${missionRow[0]} · ${missionRow[2]}</strong></div><p>${missionRow[1]} · ${c().focus.join(' · ')}</p><div><b>Model:</b> truth-pack virtual runtime</div></div>${intro('SPARKLAB V0.5','Real semantics → virtual distributed Spark experience','Safe PySpark parsing is separated from the virtual scheduler so semantic truth, physical truth and cost truth can be tested independently.')}<div class="spark-summary">${metric('Input rows',m.input)}${metric('Input size',m.bytes)}${metric('Partitions',m.parts)}${metric('Est. shuffle',m.shuffle+' GB')}${metric('Skew ratio',m.skew+'×')}${metric('Broadcast candidate',m.broadcast)}${m.baseline?metric('Without broadcast','~'+m.baseline+' GB'):''}</div><div class="spark-two-col"><div class="plan-card"><div class="card-head"><span>LOGICAL → PHYSICAL REASONING</span><strong>PySpark notebook plan</strong></div>${c().plan.map((x,i)=>`<div class="plan-row"><b>${i+1}</b><span>${x}</span>${/Exchange|Broadcast|Sort/.test(x)?`<em>${x.includes('Broadcast')?'broadcast':'wide boundary'}</em>`:''}</div>`).join('')}</div><div class="partition-card"><div class="card-head"><span>REFERENCE PARTITIONS</span><strong>Known case distribution</strong></div><div class="partition-bars">${bars.map(v=>`<div class="${v===max?'hot':''}" style="height:${Math.max(10,v/max*100)}%"></div>`).join('')}</div><div class="partition-foot"><span>Median <b>${m.median} MB</b></span><span>Largest <b>${m.largest} MB</b></span><span>Ratio <b>${m.skew}×</b></span></div></div></div><div class="section-title"><span>Stage model</span></div><div class="stages">${c().stages.map((s,i)=>`<div class="stage ${s[2]}"><b>Stage ${i+1}</b><strong>${s[0]}</strong><span>${s[1]}</span><small>${m.parts} tasks</small></div>`).join('')}</div>${runtime}${caseId==='retail'?`<div class="optimization"><div><span>BASELINE</span><strong>SortMergeJoin</strong><p>~52.8 GB modeled shuffle.</p></div><i class="arrow">→</i><div><span>DATA EVIDENCE</span><strong>dimension = 6.4 MB</strong><p>Below the 10 MB truth-pack threshold.</p></div><i class="arrow">→</i><div class="good"><span>OPTIMIZED</span><strong>BroadcastHashJoin + AQE</strong><p>~26.4 GB remains for aggregation; AQE splits the hot partition.</p></div></div>`:''}</div>`}function pipeline(){return `<div class="page">${intro('ORCHESTRATION','Airflow operates the pipeline; it is not the transformation engine','Coordinate detection, retries, backfills and publish state while notebook logic stays testable independently.')}<div class="dag">${['detect_batch','ingest_bronze','quality_gate','build_silver','dbt_gold','publish_consumer'].map((x,i)=>`<div><div class="${i<3?'ok':i===3?'warn':'idle'}"><b>${x}</b><span>${i===3?'retry-safe repair exercise':i<3?'success':'waiting'}</span></div>${i<5?'<i>↓</i>':''}</div>`).join('')}</div></div>`}
function dbt(){return `<div class="page">${intro('DBT','Silver → tested Gold contracts','Keep transformations versionable and make the consumer contract explicit.')}<div class="lineage"><div>silver.cleaned</div><i>→</i><div>stg_events</div><i>→</i><div>int_metrics</div><i>→</i><div class="gold">fct_events</div><i>+</i><div class="gold">daily_kpis</div></div></div>`}
function lake(){return `<div class="page">${intro('DUCKLAKE','Parquet-backed lakehouse state is real; Spark remains optional compute','The lab uses DuckLake because it lets you operate a real medallion lakehouse while SparkLab teaches distributed-compute reasoning separately.')}<div class="snapshot-row">${[c().snapshot-2,c().snapshot-1,c().snapshot,c().snapshot+1].map(n=>`<div class="${(ran&&n===c().snapshot+1)||(!ran&&n===c().snapshot)?'current':''}"><span>#${n}</span><strong>${n===c().snapshot+1?'Notebook commit':n===c().snapshot?'Current':'Prior'}</strong></div>`).join('')}</div><div class="principle-grid"><div class="mini"><strong>Bronze</strong><p>Immutable source-fidelity Parquet plus ingestion metadata.</p></div><div class="mini"><strong>Silver</strong><p>Typed, deduplicated, conformed and quality checked.</p></div><div class="mini"><strong>Gold</strong><p>Facts, dimensions, aggregates and consumer contracts.</p></div></div></div>`}
function quality(){return `<div class="page">${intro('QUALITY','A successful task is not enough','Validate schemas, keys, domains, relationships and freshness before publishing Gold.')}<div class="quality-table">${[['source_schema','Bronze','pass'],['business_key','Silver','pass'],['case_invariant','Silver',ran?'pass':'fail'],['gold_contract','Gold',ran?'pass':'blocked'],['freshness','Gold',ran?'pass':'fail']].map(x=>`<div><strong>${x[0]}</strong><span>${x[1]}</span><em class="${x[2]}">${x[2]}</em></div>`).join('')}</div></div>`}
function consumer(){return `<div class="page">${intro('EVIDENCE','Thin BI as proof that engineering output is useful','KPIs expose bad Gold data and provide a consumer signal without turning this into another BI product.')}<div class="kpis">${c().kpis.map((x,i)=>`<div><span>${x[0]}</span><strong>${!ran&&caseId==='mobility'&&i===0?'$4.12M':x[1]}</strong><small class="${!ran&&caseId==='mobility'&&i===0?'bad':'good'}">${!ran&&caseId==='mobility'&&i===0?'anomaly':'verified Gold'}</small></div>`).join('')}</div></div>`}
function advanced(){return `<div class="page">${intro('ADVANCED · OPTIONAL','Interoperability stays an appendix','Avro, Iceberg and Delta remain useful labs, but no longer define the product. The core stays Parquet + DuckLake + SQL/PySpark notebook practice.')}<div class="principle-grid"><div class="mini"><strong>Avro intake</strong><p>Optional CDC exercise before canonical DuckLake tables.</p></div><div class="mini"><strong>Iceberg comparison</strong><p>Compare open-table snapshot/catalog concepts.</p></div><div class="mini"><strong>Polars</strong><p>Real lazy DataFrame executor—not a claim of Spark equivalence.</p></div></div></div>`}
function page(){return ({Overview:overview,Notebook:notebook,'Spark Lab':sparklab,Pipeline:pipeline,dbt,Lakehouse:lake,Quality:quality,Consumer:consumer,Advanced:advanced}[tab])()}
function inspector(){return `<div class="inspect-head"><span>LAKEHOUSE INSPECTOR</span><strong>${c().lake}</strong><em>REAL DATA MODEL</em></div><div class="inspect-block"><span>Current snapshot</span><strong>#${c().snapshot+(ran?1:0)}</strong><small>${ran?'notebook commit':'case baseline'}</small></div><div class="inspect-block"><span>Source</span><strong>Parquet</strong><small>core curriculum format</small></div><div class="inspect-table"><span>PHYSICAL STATE</span><div><b>Rows</b><strong>${c().rows}</strong></div><div><b>Files</b><strong>${c().files}</strong></div><div><b>Size</b><strong>${c().size}</strong></div><div><b>Compute</b><strong>${env}</strong></div></div><div class="inspect-table"><span>SPARKLAB</span><div><b>Partitions</b><strong>${c().metrics.parts}</strong></div><div><b>Shuffle</b><strong>~${c().metrics.shuffle} GB</strong></div><div><b>Skew</b><strong>${c().metrics.skew}×</strong></div><div><b>Status</b><strong>SIMULATED</strong></div></div><div class="truth-small"><b>REAL</b><p>data · SQL · Parquet · DuckLake state</p><b>SIMULATED</b><p>distributed Spark runtime behavior</p></div>`}
function esc(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}
function bind(){document.querySelector('#caseSel').onchange=e=>{caseId=e.target.value;mission=0;ran=false;render()};document.querySelectorAll('[data-env]').forEach(b=>b.onclick=()=>{env=b.dataset.env;render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{mission=+b.dataset.mission;ran=false;let layer=c().missions[mission][1];tab=layer==='Spark'?'Spark Lab':layer==='Airflow'?'Pipeline':(layer==='dbt'||layer==='Gold')?'dbt':layer==='Lakehouse'?'Lakehouse':layer==='Incident'?'Quality':'Notebook';render()});document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{caseId=b.dataset.case;mission=0;ran=false;render()});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});let r=document.querySelector('#run');if(r)r.onclick=()=>{ran=true;render()};let cs=document.querySelector('#clusterSel');if(cs)cs.onchange=e=>{cluster=e.target.value;render()};document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{planMode=b.dataset.plan;render()});document.querySelectorAll('[data-sparkui]').forEach(b=>b.onclick=()=>{sparkUi=b.dataset.sparkui;render()})}
render();
